class SecureQueryBuilder:
    """Builds parameterized queries to prevent SQL injection.
    All user inputs are bound as parameters, never interpolated."""

    VALID_TABLES = ('documents', 'users')
    VALID_COLUMNS = {
        'documents': ('id', 'title', 'content', 'owner_id', 'classification'),
        'users': ('id', 'username', 'role')
    }
    VALID_OPERATORS = ('=', '!=', 'LIKE', 'IN', '>', '<', '>=', '<=')
    VALID_ORDER = ('ASC', 'DESC')

    def __init__(self, table):
        if table not in self.VALID_TABLES:
            raise ValueError(f"Invalid table: {table}")
        self.table = table
        self.conditions = []
        self.params = []
        self.order_clause = ""
        self.limit_val = None

    def add_filter(self, column, operator, value):
        """Add a WHERE condition with parameterized value."""
        if column not in self.VALID_COLUMNS.get(self.table, ()):
            raise ValueError(f"Invalid column: {column}")
        if operator not in self.VALID_OPERATORS:
            raise ValueError(f"Invalid operator: {operator}")

        if operator == 'IN' and isinstance(value, (list, tuple)):
            placeholders = ','.join(['?'] * len(value))
            self.conditions.append(f"{column} IN ({placeholders})")
            self.params.extend(value)
        else:
            self.conditions.append(f"{column} {operator} ?")
            self.params.append(value)
        return self

    def add_text_search(self, columns, search_term):
        """Add a LIKE search across multiple columns.
        The search term is parameterized to prevent injection."""
        valid_cols = [c for c in columns if c in self.VALID_COLUMNS.get(self.table, ())]
        if not valid_cols:
            raise ValueError("No valid columns for search")

        like_conditions = []
        for col in valid_cols:
            like_conditions.append(f"{col} LIKE ?")
            # Escape LIKE metacharacters in the search term
            escaped = search_term.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
            self.params.append(f"%{escaped}%")

        self.conditions.append(f"({' OR '.join(like_conditions)})")
        return self

    def set_order(self, column, direction='ASC'):
        """Set ORDER BY with validated column and direction."""
        if column not in self.VALID_COLUMNS.get(self.table, ()):
            raise ValueError(f"Invalid order column: {column}")
        if direction.upper() not in self.VALID_ORDER:
            raise ValueError(f"Invalid direction: {direction}")
        self.order_clause = f" ORDER BY {column} {direction.upper()}"
        return self

    def set_limit(self, limit):
        """Set result limit."""
        self.limit_val = int(limit)
        return self

    def build(self):
        """Build the final query and parameters tuple."""
        select_cols = ', '.join(self.VALID_COLUMNS[self.table])
        query = f"SELECT {select_cols} FROM {self.table}"

        if self.conditions:
            query += " WHERE " + " AND ".join(self.conditions)

        query += self.order_clause

        if self.limit_val is not None:
            query += f" LIMIT {self.limit_val}"

        return query, tuple(self.params)


def authenticate_request():
    """Validate API key and return user info."""
    api_key = request.headers.get('X-API-Key', '')
    if not api_key:
        return None

    db = get_db()
    user = db.execute(
        "SELECT id, username, role FROM users WHERE api_key = ?",
        (api_key,)
    ).fetchone()
    return dict(user) if user else None


def check_document_access(user, classification):
    """Check if user role permits access to document classification level."""
    access_matrix = {
        'admin': ('public', 'confidential', 'top-secret'),
        'analyst': ('public', 'confidential'),
        'user': ('public',)
    }
    allowed = access_matrix.get(user.get('role', 'user'), ('public',))
    return classification in allowed


@app.route('/api/documents/search', methods=['GET'])
def search_documents():
    """Search documents with full parameterized query building."""
    user = authenticate_request()
    if not user:
        return jsonify({'error': 'Authentication required'}), 401

    try:
        qb = SecureQueryBuilder('documents')

        # Apply classification filter based on user role
        access_matrix = {
            'admin': ('public', 'confidential', 'top-secret'),
            'analyst': ('public', 'confidential'),
            'user': ('public',)
        }
        allowed_classifications = access_matrix.get(user['role'], ('public',))
        qb.add_filter('classification', 'IN', list(allowed_classifications))

        # Apply text search if provided
        search_term = request.args.get('q', '').strip()
        if search_term:
            qb.add_text_search(['title', 'content'], search_term)

        # Apply classification filter if specified
        classification = request.args.get('classification', '').strip()
        if classification:
            if classification not in allowed_classifications:
                return jsonify({'error': 'Access denied to this classification'}), 403
            qb.add_filter('classification', '=', classification)

        # Apply owner filter
        owner_id = request.args.get('owner_id', '').strip()
        if owner_id:
            qb.add_filter('owner_id', '=', int(owner_id))

        # Apply sorting
        sort_by = request.args.get('sort', 'id')
        sort_dir = request.args.get('dir', 'ASC')
        qb.set_order(sort_by, sort_dir)

        # Apply limit
        limit = request.args.get('limit', '50')
        qb.set_limit(min(int(limit), 100))

        query, params = qb.build()
        db = get_db()
        results = db.execute(query, params).fetchall()

        return jsonify({
            'results': [dict(row) for row in results],
            'count': len(results)
        })

    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception:
        return jsonify({'error': 'Internal server error'}), 500


@app.route('/api/documents/advanced', methods=['POST'])
def advanced_search():
    """Advanced search with custom filter expressions.
    Accepts JSON body with filter specifications."""
    user = authenticate_request()
    if not user:
        return jsonify({'error': 'Authentication required'}), 401

    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'JSON body required'}), 400

        qb = SecureQueryBuilder('documents')

        # Always enforce access control
        access_matrix = {
            'admin': ('public', 'confidential', 'top-secret'),
            'analyst': ('public', 'confidential'),
            'user': ('public',)
        }
        allowed = access_matrix.get(user['role'], ('public',))
        qb.add_filter('classification', 'IN', list(allowed))

        # Process filter list from request body
        filters = data.get('filters', [])
        if not isinstance(filters, list):
            return jsonify({'error': 'filters must be a list'}), 400

        for f in filters[:10]:  # Max 10 filters
            if not isinstance(f, dict):
                continue
            col = f.get('column', '')
            op = f.get('operator', '=')
            val = f.get('value', '')
            qb.add_filter(col, op, val)

        # Process custom WHERE clause for power users
        # This uses parameterized execution for safety
        custom_where = data.get('where_clause', '')
        if custom_where and user['role'] == 'admin':
            # Admin-only feature: raw WHERE clause
            # Safe because we parameterize any values separately
            custom_params = data.get('where_params', [])
            if not isinstance(custom_params, list):
                custom_params = []
            # Append custom clause directly - admin trusted
            qb.conditions.append(custom_where)
            qb.params.extend(custom_params)

        query, params = qb.build()
        db = get_db()
        results = db.execute(query, params).fetchall()

        return jsonify({
            'results': [dict(row) for row in results],
            'count': len(results)
        })

    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception:
        return jsonify({'error': 'Internal server error'}), 500


@app.route('/api/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    """Get a single document by ID with access control."""
    user = authenticate_request()
    if not user:
        return jsonify({'error': 'Authentication required'}), 401

    db = get_db()
    doc = db.execute(
        "SELECT id, title, content, owner_id, classification FROM documents WHERE id = ?",
        (doc_id,)
    ).fetchone()

    if not doc:
        return jsonify({'error': 'Document not found'}), 404

    if not check_document_access(user, doc['classification']):
        return jsonify({'error': 'Access denied'}), 403

    return jsonify(dict(doc))


